from math import gcd
from typing import List, Tuple


def jacobi_symbol(a: int, n: int) -> int:
    """Jacobi symbol J(a|n) for odd n >= 1, computed from n alone in O(log^2 n)."""
    if n <= 0 or n % 2 == 0:
        raise ValueError("modulus must be odd and positive")
    a %= n
    result = 1
    while a != 0:
        while a % 2 == 0:
            a //= 2
            if n % 8 in (3, 5):
                result = -result
        a, n = n, a
        if a % 4 == 3 and n % 4 == 3:
            result = -result
        a %= n
    return result if n == 1 else 0


def agreement_membership(a: int, n: int) -> bool:
    """Decide a in A(N) = {(a|p) = (a|q)} using only N: A(N) = {J(a|N) = +1}."""
    return jacobi_symbol(a, n) == 1


def agreement_count_and_check(p: int, q: int) -> Tuple[int, int, bool]:
    """Return (|A(N)|, phi(N)/2, whether A(N) equals the Jacobi level set)."""
    n, phi = p * q, (p - 1) * (q - 1)

    def legendre(a: int, r: int) -> int:
        a %= r
        if a == 0:
            return 0
        return 1 if pow(a, (r - 1) // 2, r) == 1 else -1

    units: List[int] = [a for a in range(1, n) if gcd(a, n) == 1]
    hidden = {a for a in units if legendre(a, p) == legendre(a, q)}
    public = {a for a in units if agreement_membership(a, n)}
    return len(hidden), phi // 2, hidden == public


def flipping_unit(p: int, q: int) -> int:
    """The CRT witness u with (u|p) = -1 and (u|q) = +1 driving the pairing."""
    n = p * q

    def legendre(a: int, r: int) -> int:
        a %= r
        return 0 if a == 0 else (1 if pow(a, (r - 1) // 2, r) == 1 else -1)

    return next(a for a in range(1, n)
                if gcd(a, n) == 1 and legendre(a, p) == -1 and legendre(a, q) == 1)


if __name__ == "__main__":
    for p, q in [(5, 7), (11, 13), (17, 19)]:
        count, half_phi, same = agreement_count_and_check(p, q)
        print(f"N={p*q:5d}  |A(N)|={count:5d}  phi/2={half_phi:5d}  "
              f"equals Jacobi level set: {same}  flipping unit u={flipping_unit(p,q)}")

