function RHO_ORBIT(x0, N, T):
    x[0] <- x0 mod N
    for t in 0..T-1: x[t+1] <- (x[t]^2 + 1) mod N
    return x

function UNCONDITIONAL_EXTRACT(N, bound, x0):
    x <- RHO_ORBIT(x0, N, bound)          # bound = p guarantees success
    for i < j in 0..bound:                 # C(bound+1, 2) pairs
        g <- gcd(|x[j] - x[i]|, N)
        if 1 < g < N: return (i, j, g)
    return FAIL

# Correctness: reduction-compatibility gives x[t] mod p = rho^t(x0) mod p;
# pigeonhole on p states forces i < j <= p with p | x[j] - x[i];
# if q does not divide the difference then the gcd equals p exactly.
